import CoreGraphics
import XCTest
@testable import BlurtCore

/// The menu-bar chick's hop and crouch stay inside their 18 × 22 pt frame (review: the crouch's 1.1 widening cut both
/// wing nubs off flat, and the hop's tuft touched the top row).
final class GlyphPoseTests: XCTestCase {
    // MenuGlyphGeometry.swift (generated by assets/brand/chick.swift): the chick's ink and foot in its 18 pt box
    let ink = CGRect(x: 0.4, y: 0.758, width: 17.2, height: 16.242)
    let foot: CGFloat = 17, box: CGFloat = 18, bar: CGFloat = 22

    func frameInk(squash: CGFloat, lift: CGFloat) -> CGRect {
        let k = GlyphPose.scales(squash: squash, lift: lift, ink: ink, foot: foot, box: box, barHeight: bar)
        let top = (bar - box) / 2                                      // the box's top in the frame (y down)
        let mid = box / 2
        return CGRect(x: mid + (ink.minX - mid) * k.x, y: top + foot - lift - (foot - ink.minY) * k.y,
                      width: ink.width * k.x, height: (foot - ink.minY) * k.y)
    }

    func testRestIsUntouched() {
        let k = GlyphPose.scales(squash: 0, lift: 0, ink: ink, foot: foot, box: box, barHeight: bar)
        XCTAssertEqual(k.x, 1); XCTAssertEqual(k.y, 1)
    }

    func testEveryHopFrameKeepsItsInkInside() {
        // MenuGlyph.frame's curve, quantised as it is (crouch 0.1, hop 1.5 pt up and 5 % taller, landing 0.07)
        for i in 0...100 {
            let u = Double(i) / 100
            let lift = u < 0.18 ? 0 : u < 0.72 ? 1.5 * CGFloat(sin(.pi * (u - 0.18) / 0.54)) : 0
            let squash = u < 0.18 ? 0.1 * CGFloat(sin(.pi * u / 0.36)) : u < 0.72 ? -0.05 * CGFloat(sin(.pi * (u - 0.18) / 0.54))
                : 0.07 * CGFloat(sin(.pi * (u - 0.72) / 0.28))
            let r = frameInk(squash: squash, lift: lift)
            XCTAssertGreaterThanOrEqual(r.minX, min(ink.minX, GlyphPose.margin) - 1e-9, "u \(u)")
            XCTAssertLessThanOrEqual(r.maxX, box - min(ink.minX, GlyphPose.margin) + 1e-9, "u \(u)")
            XCTAssertGreaterThanOrEqual(r.minY, GlyphPose.margin - 1e-9, "u \(u)")
            XCTAssertLessThanOrEqual(r.maxY, bar, "u \(u)")
        }
    }

    func testTheCrouchStillCrouches() {
        let k = GlyphPose.scales(squash: 0.1, lift: 0, ink: ink, foot: foot, box: box, barHeight: bar)
        XCTAssertEqual(k.y, 0.9, accuracy: 1e-9)                       // shorter, as before
        XCTAssertLessThanOrEqual(k.x, 1.1)
        let hop = GlyphPose.scales(squash: -0.05, lift: 1.5, ink: ink, foot: foot, box: box, barHeight: bar)
        XCTAssertGreaterThan(hop.y, 1.03)                               // still visibly stretched
        XCTAssertLessThan(hop.x, 1)
    }
}
